import type { EcoAction, EcoActionUserType } from "@/src/data/actions";

/**
 * Route-local filter vocabulary for the guide checklist. Every value here is
 * derived deterministically from fields that already exist on `EcoAction`
 * (`eligibleUserTypes`, `estimatedCostRangeManwon`, `supportEligible`) — no
 * fixture data is changed or duplicated, this module only adds route-local
 * labels/grouping on top of it.
 */

export type AudienceFilter = "all" | "owner" | "tenant";

export interface AudienceOption {
  value: AudienceFilter;
  label: string;
}

export const AUDIENCE_OPTIONS: AudienceOption[] = [
  { value: "all", label: "전체" },
  { value: "owner", label: "임대인(소유주)" },
  { value: "tenant", label: "임차인" },
];

export type BudgetFilter = "all" | "tier1" | "tier2" | "tier3";

export interface BudgetOption {
  value: BudgetFilter;
  label: string;
}

export const BUDGET_OPTIONS: BudgetOption[] = [
  { value: "all", label: "전체 예산" },
  { value: "tier1", label: "50만원 이하" },
  { value: "tier2", label: "50만원 초과 ~ 500만원 이하" },
  { value: "tier3", label: "500만원 초과" },
];

/** Buckets an action's minimum implementation cost into one of three route-local budget tiers. */
export function getBudgetTier(action: EcoAction): Exclude<BudgetFilter, "all"> {
  const min = action.estimatedCostRangeManwon.min;
  if (min <= 50) return "tier1";
  if (min <= 500) return "tier2";
  return "tier3";
}

export interface GuideFilterState {
  audience: AudienceFilter;
  budget: BudgetFilter;
  supportOnly: boolean;
}

export const DEFAULT_GUIDE_FILTER_STATE: GuideFilterState = {
  audience: "all",
  budget: "all",
  supportOnly: false,
};

/** Applies the owner/tenant, budget-tier, and support-only filters to the full action list. */
export function filterActions(actions: EcoAction[], filters: GuideFilterState): EcoAction[] {
  return actions.filter((action) => {
    if (filters.audience !== "all") {
      const audience: EcoActionUserType = filters.audience;
      if (!action.eligibleUserTypes.includes(audience)) return false;
    }
    if (filters.budget !== "all" && getBudgetTier(action) !== filters.budget) {
      return false;
    }
    if (filters.supportOnly && !action.supportEligible) {
      return false;
    }
    return true;
  });
}
