"use client";

import { useId, useMemo, useState } from "react";
import type { EcoAction, EcoActionDifficulty } from "@/src/data/actions";
import { Checkbox, RadioGroup, Select, Tag } from "@/src/components/ui";
import { formatManwon } from "@/src/lib/format";
import { useChecklistStorage } from "../_lib/use-checklist-storage";
import {
  AUDIENCE_OPTIONS,
  BUDGET_OPTIONS,
  DEFAULT_GUIDE_FILTER_STATE,
  filterActions,
  getBudgetTier,
  type AudienceFilter,
  type BudgetFilter,
  type GuideFilterState,
} from "../_lib/guide-filters";

export interface GuideChecklistProps {
  buildingId: string;
  actions: EcoAction[];
}

const DIFFICULTY_LABEL: Record<EcoActionDifficulty, string> = {
  easy: "쉬움",
  medium: "보통",
  hard: "어려움",
};

const DIFFICULTY_TONE_VARS: Record<EcoActionDifficulty, { fg: string; bg: string }> = {
  easy: { fg: "--status-good", bg: "--status-good-soft" },
  medium: { fg: "--status-caution", bg: "--status-caution-soft" },
  hard: { fg: "--status-warn", bg: "--status-warn-soft" },
};

/**
 * Client island: owner/tenant, budget, and support-only filters over the
 * fixed `actions` list, plus a checklist whose completion state persists to
 * guarded `localStorage` (see `useChecklistStorage`). Everything else on the
 * guide page is a plain Server Component.
 */
export function GuideChecklist({ buildingId, actions }: GuideChecklistProps) {
  const [filters, setFilters] = useState<GuideFilterState>(DEFAULT_GUIDE_FILTER_STATE);
  const { completed, toggle, hydrated } = useChecklistStorage(buildingId);
  const budgetSelectId = useId();
  const progressId = useId();

  const filteredActions = useMemo(() => filterActions(actions, filters), [actions, filters]);
  const completedCount = useMemo(
    () => actions.filter((action) => completed[action.id]).length,
    [actions, completed],
  );
  const budgetLabel = (value: Exclude<BudgetFilter, "all">) =>
    BUDGET_OPTIONS.find((option) => option.value === value)?.label ?? "";

  return (
    <div className="flex flex-col gap-[var(--space-6)]">
      <div className="flex flex-col gap-[var(--space-4)] rounded-[var(--radius-lg)] border border-[var(--border-subtle)] bg-[var(--surface-sunken)] p-[var(--pad-card)] sm:flex-row sm:flex-wrap sm:items-end sm:gap-[var(--space-6)]">
        <RadioGroup
          legend="누구를 위한 실천인가요?"
          orientation="horizontal"
          value={filters.audience}
          onValueChange={(value) =>
            setFilters((current) => ({ ...current, audience: value as AudienceFilter }))
          }
          options={AUDIENCE_OPTIONS.map((option) => ({ value: option.value, label: option.label }))}
        />

        <Select
          id={budgetSelectId}
          label="예산 범위"
          value={filters.budget}
          onChange={(event) =>
            setFilters((current) => ({ ...current, budget: event.target.value as BudgetFilter }))
          }
          options={BUDGET_OPTIONS.map((option) => ({ value: option.value, label: option.label }))}
        />

        <Checkbox
          label="지원사업 연계 항목만 보기"
          checked={filters.supportOnly}
          onChange={(event) =>
            setFilters((current) => ({ ...current, supportOnly: event.target.checked }))
          }
        />
      </div>

      <p id={progressId} aria-live="polite" className="text-[length:var(--text-label-size)] font-bold text-[var(--text-strong)]">
        전체 {actions.length}개 중 {completedCount}개 완료
        {!hydrated ? <span className="sr-only"> (저장된 완료 기록을 불러오는 중)</span> : null}
      </p>

      {filteredActions.length === 0 ? (
        <p className="rounded-[var(--radius-lg)] border border-dashed border-[var(--border-subtle)] p-[var(--pad-card)] text-center text-[var(--text-body-size)] text-[var(--text-muted)]">
          조건에 맞는 실천 항목이 없어요. 필터를 조정해 보세요.
        </p>
      ) : (
        <ol className="flex flex-col gap-[var(--space-3)]" aria-describedby={progressId}>
          {filteredActions.map((action) => {
            const isDone = Boolean(completed[action.id]);
            const tone = DIFFICULTY_TONE_VARS[action.difficulty];
            const tier = getBudgetTier(action);

            return (
              <li
                key={action.id}
                className="rounded-[var(--radius-lg)] border border-[var(--border-subtle)] bg-[var(--surface-card)] p-[var(--pad-card)]"
              >
                <div className="flex items-start gap-[var(--space-4)]">
                  <Checkbox
                    checked={isDone}
                    onChange={() => toggle(action.id)}
                    label={<span className="sr-only">{action.title} 완료로 표시</span>}
                    className="mt-[3px]"
                  />
                  <div className="flex-1">
                    <div className="flex flex-wrap items-center gap-[var(--space-2)]">
                      <span className="text-[length:var(--text-caption-size)] font-bold text-[var(--text-muted)]">
                        {action.category}
                      </span>
                      <span
                        className="rounded-[var(--radius-pill)] px-[var(--space-2)] py-0.5 text-[length:var(--text-caption-size)] font-bold"
                        style={{ color: `var(${tone.fg})`, backgroundColor: `var(${tone.bg})` }}
                      >
                        난이도 {DIFFICULTY_LABEL[action.difficulty]}
                      </span>
                    </div>
                    <h3
                      className={
                        isDone
                          ? "mt-[var(--space-2)] text-[length:var(--text-subhead-size)] font-bold text-[var(--text-muted)] line-through"
                          : "mt-[var(--space-2)] text-[length:var(--text-subhead-size)] font-bold text-[var(--text-strong)]"
                      }
                    >
                      {action.title}
                    </h3>
                    <p className="mt-[var(--space-1)] text-[length:var(--text-body-size)] leading-[var(--text-body-lh)] text-[var(--text-body)]">
                      {action.description}
                    </p>
                    <p className="mt-[var(--space-3)] text-[length:var(--text-label-size)] font-bold text-[var(--status-good)]">
                      월 {formatManwon(action.monthlySavingsManwon)} 절감 예상 · 초기 비용{" "}
                      {formatManwon(action.estimatedCostRangeManwon.min)}~
                      {formatManwon(action.estimatedCostRangeManwon.max)}
                    </p>
                    <div className="mt-[var(--space-3)] flex flex-wrap gap-[var(--space-2)]">
                      {action.eligibleUserTypes.includes("owner") ? (
                        <Tag tone="teal">임대인 가능</Tag>
                      ) : null}
                      {action.eligibleUserTypes.includes("tenant") ? (
                        <Tag tone="celadon">임차인 가능</Tag>
                      ) : null}
                      <Tag tone="neutral">{budgetLabel(tier)}</Tag>
                      {action.supportEligible ? <Tag tone="vanilla">지원사업 연계</Tag> : null}
                    </div>
                  </div>
                </div>
              </li>
            );
          })}
        </ol>
      )}
    </div>
  );
}
